{
  "families": [
    {
      "family": "iterative",
      "ranges": [
        {"param": "data_width", "low": 12, "high": 20, "choices": null},
        {"param": "n_iter", "low": 10, "high": 20, "choices": null},
        {"param": "angle_guard", "low": 0, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 50,
      "why": "Most area-efficient family: one shared datapath with barrel shifters. Throughput = Fmax/(N+3) MSPS; for N<=20 and typical Fmax > 23 MHz this easily meets the 1 MSPS constraint. Focus budget here to find the minimal data_width and n_iter that satisfy max_abs_err <= 2^-10."
    },
    {
      "family": "unrolled_k",
      "ranges": [
        {"param": "data_width", "low": 12, "high": 20, "choices": null},
        {"param": "n_iter", "low": 10, "high": 20, "choices": null},
        {"param": "angle_guard", "low": 0, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "k", "low": 2, "high": 4, "choices": null}
      ],
      "budget_share": 20,
      "why": "Small k (2-4) reduces cycles per result but adds parallel micro-rotation hardware. Since throughput is already satisfied by iterative, this family is likely dominated, but it uses fixed shifts (no barrel shifters) and may be area-competitive for small k. A modest share checks whether it can beat iterative on luts_plus_ffs."
    },
    {
      "family": "pipelined_m",
      "ranges": [
        {"param": "data_width", "low": 12, "high": 20, "choices": null},
        {"param": "n_iter", "low": 10, "high": 20, "choices": null},
        {"param": "angle_guard", "low": 0, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "m", "low": 4, "high": 8, "choices": null}
      ],
      "budget_share": 25,
      "why": "Large m (4-8) registers every m stages, keeping pipeline register count low while providing 1 result/cycle. Uses fixed shifts (no barrel shifters), so it may be area-competitive with iterative. This family is a strong candidate for the area-optimal design if the register overhead is lower than the barrel-shifter cost."
    },
    {
      "family": "pipelined",
      "ranges": [
        {"param": "data_width", "low": 12, "high": 18, "choices": null},
        {"param": "n_iter", "low": 10, "high": 16, "choices": null},
        {"param": "angle_guard", "low": 0, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 5,
      "why": "Full pipeline with one register per micro-rotation gives 1 result/cycle but has the highest register count and is likely the largest area. A small share confirms whether it is dominated and ensures the Pareto front is not missing an unexpected corner."
    }
  ],
  "rationale": "The spec requires >=1 MSPS and max_abs_err <= 2^-10. The output LSB is 2^-(data_width-2), so data_width must be at least 12 to have any chance of meeting the error bound; n_iter >= 10 is needed for sufficient CORDIC accuracy. The iterative family shares its datapath and is the most area-efficient, so it receives the largest share. unrolled_k and pipelined_m use fixed shifts (no barrel shifters) and may trade area differently; pipelined_m with large m keeps 1/cycle throughput while limiting register count, making it a strong area competitor. Full pipelined is included with a small share to verify it is dominated. All ranges are within the registry and focus on the low-area, moderate-accuracy region where the Pareto front is expected."
}

{
  "decision": "map_front",
  "rationale": "The feasible front is entirely iterative (27 designs, luts_plus_ffs 273..595, accuracy_bits 10.9..23.6); the other families are dominated on the two objectives — best unrolled_k area 374, pipelined_m 872, pipelined 1490, all worse than iterative's 273, and their high throughput (up to 273 MSPS) buys nothing because the throughput constraint is only >=1 MSPS and is met by every design (0% violations). The front already spans the full registry data_width range (14..28) and n_iter 12..30, so there is no obviously under-explored region to refine or widen. With the HV reference at (1500, 10), the dominant HV term is the rectangle above the highest-accuracy point (595, 23.6), so the remaining 200-eval budget is best spent letting NSGA-II map the whole iterative front (seeded with it) to sharpen the staircase and confirm the accuracy ceiling near data_width=28, rather than narrowing onto the min-area corner the selection rule would pick.",
  "next_plan": null
}
